import{_ as p}from"./chunks/image-002.Dp2-bnLm.js";import{_ as t}from"./chunks/image-011.CVj6F8GH.js";import{_ as o,o as _,c as l,a3 as i}from"./chunks/framework.DdpBa4_E.js";const y=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/yan-tie-lun/71-周秦第五十七.md","filePath":"books/yan-tie-lun/71-周秦第五十七.md","lastUpdated":1784092560000}'),r={name:"books/yan-tie-lun/71-周秦第五十七.md"};function s(e,a,n,m,c,d){return _(),l("div",null,[...a[0]||(a[0]=[i('<p>周秦第五十七 【题解】</p><p>本篇以“周秦”为题，西周是礼治的代表，秦朝是法治的代表，因此本篇所辩论的是礼治与法治问题。御史坚持以严刑峻法治国，他的理由是：“立法制辟，若临百仞之壑，握火蹈刃，则民畏忌，而无敢犯禁矣。”文学认为，治国应该运用礼乐教化的方法，刑罚是礼治失效之后所采取的措施，“周其礼而明其教，礼周教明，不从者然后等之以刑。”御史与文学的观点分歧，实际上是法家与儒家在治国思路上的根本差异。</p><p>御史曰：“《春秋》无名号，谓之云盗，所以贱刑人而绝之人伦也[(1)]。故君不臣[(2)]，士不友[(3)]，于闾里无所容[(4)]。故民耻犯之[(5)]。今不轨之民，犯公法以相宠[(6)]，举弃其亲[(7)]，不能伏节死理[(8)]，遁逃相连[(9)]，自陷于罪，其被刑戮，不亦宜乎？一室之中，父兄之际，若身体相属，一节动而知于心。故今自关内侯以下[(10)]，比地于伍[(11)]，居家相察[(12)]，出入相司[(13)]，父不教子，兄不正弟，舍是谁责乎？”</p><p>【注释】</p><p>[(1)]《春秋》无名号，谓之云盗，所以贱刑人而绝之人伦也：《春秋穀梁传·昭公二十年》：“秋，盗杀卫侯之兄辄。盗，贱也。”贱，贱视。人伦，人类。</p><p>[(2)]君不臣：君主不把罪人看做臣子。</p><p>[(3)]士不友：士不把罪人视为朋友。</p><p>[(4)]闾里：乡里。容：立足容身。</p><p>[(5)]耻：原作“始”，据郭沫若说校改。</p><p>[(6)]相宠：互相以为光荣。</p><p>[(7)]举：完全。</p><p>[(8)]伏节死理：低头承认死罪。伏节，伏罪。</p><p>[(9)]遁逃相连：不断地逃窜。</p><p>[(10)]关内侯：汉代第十九级爵名，仅有侯爵名号而无封邑，住在关内，故称关内侯。</p><p>[(11)]比地于伍：居地挨近的五家编为一伍。比，比邻。</p><p>[(12)]居家相察：在家时各户相互观察。</p><p>[(13)]出入相司：进出互相监督。司，通“伺”，窥察。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>御史说：“《春秋》不书写罪人的姓名与位号，称他们为‘盗’，是以此贱视罪人，不把他们视为人类。因此君主不把罪人视为臣民，士不把罪人视为朋友，罪人在乡里无地自容。因此民众耻于犯罪。如今一些不法之民，触犯国法之后，互相以为光荣，完全抛弃亲属，不能低头认罪，不断地逃窜，他自己陷于犯罪，被官府判刑杀头，不是适宜的吗？一家之中，父兄之间的关系，如同身体各个部位相连一样，一个关节触动，心里都会知道。因此现在从关内侯以下，居地挨近的五家被编为一伍，在家时各家各户相互观察，进出互相监督，父亲不教好儿子，兄长不纠正弟弟，除了父兄，还去追究谁的责任呢？”</p><p>文学曰：“古者，周其礼而明其教[(1)]，礼周教明，不从者然后等之以刑[(2)]，刑罚中[(3)]，民不怨。故舜施四罪而天下咸服[(4)]，诛不仁也。轻重各服其诛，刑必加而无赦，赦惟疑者[(5)]。若此，则世安得不轨之人而罪之？今杀人者生，剽攻窃盗者富[(6)]。故良民内解怠[(7)]，辍耕而陨心[(8)]。古者，君子不近刑人，刑人非人也[(9)]，身放殛而辱后世[(10)]，故无贤不肖，莫不耻也。今无行之人，贪利以陷其身，蒙戮辱而捐礼义[(11)]，恒于苟生[(12)]。何者？一日下蚕室[(13)]，创未瘳[(14)]，宿卫人主[(15)]，出入宫殿，由得受奉禄[(16)]，食大官享赐[(17)]，身以尊荣，妻子获其饶[(18)]。故或载卿相之列，就刀锯而不见闵[(19)]，况众庶乎？夫何耻之有！今废其德教[(20)]，而责之以礼义，是虐民也。</p><p>【注释】</p><p>[(1)]周其礼：周密地规定礼仪。明其教：明确地实施教化。</p><p>[(2)]等：按不同等级。</p><p>[(3)]中：适中。</p><p>[(4)]舜施四罪而天下咸服：《尚书·尧典》载：“流共工于幽州，放</p><p><img src="'+t+'" alt="" loading="lazy"></p><p>兜于崇山，窜三苗于三危，殛鲧于羽山，四罪而天下咸服。”</p><p>[(5)]赦惟疑者：只赦免那些证据不足的嫌疑犯。</p><p>[(6)]剽攻：抢劫。</p><p>[(7)]解：通“懈”。</p><p>[(8)]陨心：失去信心。</p><p>[(9)]刑人非人也：《春秋公羊传·襄公二十九年》载：“刑人则曷谓之阍？刑人非其人也。君子不近刑人，近刑人，轻死之道也。”</p><p>[(10)]放：流放。殛（jí）：诛杀。</p><p>[(11)]捐：抛弃。</p><p>[(12)]恒于苟生：常年苟且偷生。恒，常。</p><p>[(13)]蚕室：古代被施宫刑之后，为防感染发炎，犯人被放在温暖的囚室。这种囚室如同养蚕小屋，故称蚕室。</p><p>[(14)]创：受刑创口。瘳（chōu）：痊愈，愈合。</p><p>[(15)]宿卫：在皇宫值夜班守卫。</p><p>[(16)]由得：原作“得由”，据陈遵默、王利器说校改。由，通“犹”。奉，通“俸”。</p><p>[(17)]食大官：秦汉有大官令丞，主管皇帝膳食。宦官由于宿卫宫廷，故能有机会吃到皇帝赏赐的御厨食物。大，读为“太”。</p><p>[(18)]饶：富饶。</p><p>[(19)]刀锯：刀用于割刑，锯用于刖刑，此处指刑具。闵：同“悯”，怜悯，引申为伤心。</p><p>[(20)]今废其德教：“今”字原无，据王利器说校补。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>文学说：“古时候，周密地规定礼仪，明确地实施教化。礼仪周密了，教化明确了，然后对不听从的人按照不同等级施行刑罚，刑罚适中，民众不会怨恨。因此帝舜对共工、</p><p><img src="'+t+'" alt="" loading="lazy"></p><p>兜、三苗、鲧四大罪人实施惩罚，天下人都为之信服，这是因为帝舜诛讨的是不仁之人。无论是轻罪还是重罪都各服处罚，坚决实施刑罚而没有赦免，所赦免的只有那些证据不足的嫌疑犯。如果能够做到这样，那么世上哪里会有不法之人而对他们定罪处罚呢？如今杀人的人可以活着，抢劫盗窃的人当富翁。因此良民百姓内心懈怠，放弃耕作而失去信心。古时候，君子不接近受过刑的人，受过刑的人不能算一个人，他们或被流放，或被杀死，给他们的后代带来羞辱，因此无论是贤人还是不肖之人，没有人不感到羞耻的。如今那些品行不端的人，贪得财利以致身陷牢狱之灾，蒙受刑罚耻辱而捐弃礼义，常年苟且偷生。为什么会这样呢？这是因为他们受宫刑进蚕室之后，创伤还没有愈合，就到皇宫值班守卫君主，出入宫殿之中，还能享受朝廷俸禄，吃御厨赐给的饭食，自己安富尊荣，妻子儿女过着富饶的生活。因此有人身居卿相之位，蒙受刀锯之刑却不见伤心，何况是广大庶民呢？这还有什么羞耻！如今废除了道德教化，却以礼义来苛责民众，这是虐待民众啊。</p><p>《春秋传》曰：‘子有罪，执其父。臣有罪，执其君，听失之大者也。’[(1)]今以子诛父，以弟诛兄，亲戚相坐[(2)]，什伍相连[(3)]，若引根本之及华叶[(4)]，伤小指之累四体也[(5)]。如此，则以有罪反诛无罪[(6)]，无罪者寡矣。臧文仲治鲁[(7)]，胜其盗而自矜[(8)]。子贡曰[(9)]：‘民将欺，而况盗乎[(10)]！’故吏不以多断为良，医不以多刺为工[(11)]。子产刑二人[(12)]，杀一人，道不拾遗，而民无诬心[(13)]。故为民父母，以养疾子[(14)]，长恩厚而已[(15)]。自首匿相坐之法立[(16)]，骨肉之恩废，而刑罪多矣[(17)]。父母之于子，虽有罪犹匿之，其不欲服罪尔[(18)]。闻子为父隐，父为子隐[(19)]，未闻父子之相坐也。闻兄弟缓追以免贼[(20)]，未闻兄弟之相坐也。闻恶恶止其人[(21)]，疾始而诛首恶[(22)]，未闻什伍而相坐也[(23)]。《老子》曰：‘上无欲而民朴，上无事而民自富。’[(24)]君君臣臣，父父子子[(25)]。比地何伍[(26)]，而执政何责也？”</p><p>【注释】</p><p>[(1)]子有罪，执其父。臣有罪，执其君，听失之大者也：见于《春秋公羊传·成公十六年》。听，听讼断案。失，错误。</p><p>[(2)]坐：牵连。</p><p>[(3)]什伍：古代五家为伍，两伍为什。</p><p>[(4)]引：拉，拔。华：花。</p><p>[(5)]累：拖累。四体：四肢。</p><p>[(6)]反诛：王利器说，当作“诛及”。</p><p>[(7)]臧文仲：春秋时期鲁国大夫，臧氏，名辰，谥文，因排行第二被后人称为臧文仲。</p><p>[(8)]自矜：自我夸耀。</p><p>[(9)]子贡：孔子弟子，善于辞令，擅长外交。</p><p>[(10)]而况盗乎：“况”下原有“民”字，据卢文弨、王利器说校删。</p><p>[(11)]刺：针灸。</p><p>[(12)]子产：春秋时期郑国贤相。</p><p>[(13)]诬心：欺骗心理。</p><p>[(14)]疾子：有病的儿子。</p><p>[(15)]长恩厚：多施厚恩。</p><p>[(16)]首匿：首谋藏匿罪人。</p><p>[(17)]而刑罪多矣：“矣”字原无，据王利器说校补。</p><p>[(18)]其：原作“岂”，据王利器说校改。</p><p>[(19)]子为父隐，父为子隐：《论语·子路》载孔子曰：“父为子隐，子为父隐，直在其中矣。”隐，隐瞒。按，“闻”字原错在“刑罪多矣”之下，据陈遵默说校改。</p><p>[(20)]闻兄弟缓追以免贼：《春秋公羊传·闵公二年》：“庆父弑二君，何以不诛？将而不免，遏恶也。既而不可及，缓追逸贼，亲亲之道也。”</p><p>[(21)]恶恶止其人：厌恶恶人，仅止于恶人自身。《春秋公羊传·昭公二十年》：“恶恶止其身，善善及子孙。”</p><p>[(22)]疾始而诛首恶：痛恨始作俑者而诛为首作恶者。《春秋公羊传·僖公十七年》：“君子恶恶也疾始，善善也乐终。”</p><p>[(23)]未闻什伍而相坐也：而，原作“之”。“也”字原无，据王利器说校改。</p><p>[(24)]上无欲而民朴，上无事而民自富：见于《老子》第五十七章。</p><p>[(25)]君君臣臣，父父子子：见于《论语·颜渊》。</p><p>[(26)]比地何伍：比地而居，何必五家编为一伍。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>《春秋公羊传·成公十六年》说：‘儿子有罪，抓捕他的父亲。臣子有罪，抓捕他的君主，这是听讼断案过程中最大的失误。’如今因为儿子犯罪而处罚父亲，因为弟弟犯罪而处罚兄长，亲戚之间互相牵连，十家五家之间互相连坐，这就如同拔起树木根本累及花朵树叶，伤害小指而拖累四肢。这样的话，就因为一人有罪而诛及那些无罪的亲属和邻居，天下没有罪的人就很少了。春秋时期臧文仲治理鲁国，战胜盗贼之后自我夸耀。孔子弟子子贡说：‘民众都要欺骗了，何况是盗贼呢！’因此对执法官员吏来说，不能因为他断案多就称他为好官，对于医生来说，不能因为他针灸多就称他为良医。春秋时期郑国执政大夫子产对两个罪人施刑，杀死一个罪人，结果郑国道不拾遗，民众也没有欺骗之心。因此身为民众父母官，对民众就要像抚养生病的孩子一样，对民众多施厚恩而已。自从汉家设置首谋藏匿罪人互相牵连的法律之后，父子兄弟骨肉的恩情废掉了，受刑定罪的人多了。父母对于子女，即使有罪仍然将他们藏匿起来，不过是不想承担牵连之罪罢了。我只听说过儿子为父亲隐瞒，父亲为儿子隐瞒，没有听说过父子互相牵连。我听说过兄弟之间放缓追究以便让贼人逃脱，没有听说兄弟之间互相牵连。听说过厌恶恶人，仅止其人本身，听说过痛恨始作俑者而诛为首作恶者，没有听说十家五家互相连坐。《老子》第五十七章说：‘在上位者没有过多欲望，民风自然会淳朴；在上位者不要管得太宽，民众自然会富裕。’君像君，臣像臣，父像父，子像子。即使是比邻而居，又何必将五家编为一伍，执政者又何必责令他们互相监督呢？”</p><p>御史曰：“夫负千钧之重，以登无极之高[(1)]，垂峻崖之峭谷[(2)]，下临不测之渊，虽有庆忌之捷[(3)]，贲、育之勇[(4)]，莫不震慑悼栗者[(5)]，知坠则身首肝脑涂山石也。故未尝灼而不敢握火者[(6)]，见其有灼也。未尝伤而不敢握刃者，见其有伤也。彼以知为非[(7)]，罪之必加，而戮及父兄，必惧而为善。故立法制辟[(8)]，若临百仞之壑，握火蹈刃，则民畏忌，而无敢犯禁矣。慈母有败子，小不忍也。严家无悍虏[(9)]，笃责急也[(10)]。今不立严家之所以制下，而修慈母之所以败子，则惑矣。”</p><p>【注释】</p><p>[(1)]无极：没有极点，看不到山顶。</p><p>[(2)]垂：接近，靠近。</p><p>[(3)]庆忌：春秋末年吴国勇士。捷：敏捷。原作“健”，据张敦仁说校改。</p><p>[(4)]贲、通：孟贲、夏育，为古代著名勇士。</p><p>[(5)]震慑悼栗：心惊胆战。栗，通“慄”。</p><p>[(6)]灼：烧伤。《淮南子·氾论训》：“故未尝灼而不敢握火者，见其有所烧也；未尝伤而不敢握刃者，见其有所害也。”</p><p>[(7)]以：通“已”。</p><p>[(8)]辟：法。</p><p>[(9)]严家：严厉的家庭。悍虏：强悍的家奴。《韩非子·显学》：“夫严家无悍虏，而慈母有败子。”</p><p>[(10)]笃责：督责，管教。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>御史说：“背负千钧重担，来攀登望不到顶的高峰，接近悬崖峭壁，下临深不可测的深渊，即使有庆忌的敏捷，孟贲、夏育的勇猛，没有人不为之心惊胆战，这是因为他们深知一旦掉下去，就会摔得粉身碎骨，肝脑涂地。因此人们未尝被灼伤而不敢用手握火，是因为他看到有人被灼伤。人们未尝被割伤而不敢用手握刀刃，是因为他看到过有人被割伤。人们已经知道为非作歹，一定要被判罪，而且连累到他的父兄，必定会畏惧而改恶从善。因此制定法律，就如同面临百仞山谷，如同手握碳火，脚踩刀刃，这样民众就会畏惧忌惮，就没有人敢于违犯禁令了。慈母会有败家之子，这是因为她不忍心对孩子的小错误进行惩罚。严厉的家庭没有强悍家奴，这是因为管教严格。如今不制定严厉家庭管教下人的措施，却采取慈母培养败家子的方法，那就十分糊涂了。”</p><p>文学曰：“纣为砲烙之刑[(1)]，而秦有收帑之法[(2)]，赵高以峻文决罪于内[(3)]，百官以峭法断割于外[(4)]，死者相枕席[(5)]，刑者相望，百姓侧目重足[(6)]，不寒而栗。《诗》云：‘谓天盖高，不敢不局。谓地盖厚，不敢不蹐。哀今之人，胡为虺蜥！’[(7)]方此之时，岂特冒蹈刃哉[(8)]？然父子相背[(9)]，兄弟相嫚[(10)]，至于骨肉相残，上下相杀。非刑轻而罚不必，令太严而仁恩不施也[(11)]。故政宽则下亲其上[(12)]，政严则民谋其主[(13)]，晋厉以幽[(14)]，二世见杀[(15)]，恶在峻法之不犯[(16)]，严家之无悍虏也？圣人知之，是以务和而不务威[(17)]。故高皇帝约秦苛法[(18)]，以慰怨毒之民[(19)]，而长和睦之心，唯恐刑之重而德之薄也。是以恩施无穷[(20)]，泽流后世。商鞅、吴起以秦、楚之法为轻而累之[(21)]，上危其主，下没其身，或非特慈母乎！”</p><p>【注释】</p><p>[(1)]纣为砲烙之刑：《史记·殷本纪》载：“百姓怨望而诸侯有畔者，于是纣乃重刑辟，有炮格之法。”炮格，通“砲烙”，将犯人绑在烧红的铜柱之上。</p><p>[(2)]收帑之法：将犯人妻子收录为官府奴婢。帑，通“孥（nú）”，妻子儿女。</p><p>[(3)]峻文：严峻的法律条文。决罪：定罪。内：朝廷。</p><p>[(4)]峭法：严刑峻法。断割：指肢体被斩断刺割。</p><p>[(5)]枕席：枕藉，指尸体横七竖八躺在一起。</p><p>[(6)]侧目重足：侧目而视，重足而立，形容畏惧情形。</p><p>[(7)]谓天盖高，不敢不局。谓地盖厚，不敢不蹐（jí）。哀今之人，胡为虺（huǐ）蜥（xī）：见于《诗经·小雅·正月》，但缺“维号斯言，有伦有脊”二句。盖，通“盍”，何。局，一作“跼”，伛偻着身子。蹐，小步走，不敢迈开大步。胡，何。虺，毒蛇。蜥，蜥蜴。</p><p>[(8)]岂特冒蹈刃哉：“冒”下脱一“火”字。</p><p>[(9)]背：背弃。</p><p>[(10)]嫚：欺骗。原作“漫”，据王利器说校改。</p><p>[(11)]令太严而仁恩不施也：“也”字原无，据王利器说校补。</p><p>[(12)]故政宽则下亲其上：“其”字原无，据王利器说校补。</p><p>[(13)]政严则民谋其主：“其”字原无，据王利器说校补。</p><p>[(14)]晋厉以幽：晋厉公被晋国大夫栾书、中行偃囚禁而死。幽，囚禁。</p><p>[(15)]二世见杀：秦二世胡亥被赵高所杀。</p><p>[(16)]恶：通“乌”，哪里。</p><p>[(17)]和：原作“知”，据王利器说校改。</p><p>[(18)]高皇帝约秦苛法：《史记·高祖本纪》载刘邦入关之后谕告民众：“与父老约，法三章耳：杀人者死，伤人及盗抵罪。余悉去秦法。”约，简化。</p><p>[(19)]以慰怨毒之民：怨毒，怨恨，憎恶。“以”字原无，据王利器说校补。</p><p>[(20)]恩施：原作“施恩”，据王利器说校补。</p><p>[(21)]累：增加。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>文学说：“殷纣王创造了炮烙酷刑，秦朝有收录罪人妻子儿女为官府奴婢的法律，赵高在朝廷内按照严峻的法律条文定罪，百官在各郡县以酷法斩断刺割民众的身体，被杀死的人相互枕藉，受刑的人相望于道，老百姓侧目而视，重足而立，不寒而栗。《诗经·小雅·正月》写道：‘天空是何等的高，却不敢不弯下身子。大地是何等的厚，却不敢不小步走路。可哀的是当今之人，为何都成毒蛇蜥蜴！’那个时候，岂止是冒着烈火、踩踏刀刃呢？但是父子互相背弃，兄弟互相欺骗，甚至于骨肉相残，上下相杀。这不是由于刑法太轻而执罚不坚决，而是因为法令太严厉而不施仁义恩德。因此政令宽松就会下亲其上，政令苛严就会导致民众谋害其主，晋厉公被大夫幽囚而死，秦二世胡亥被赵高杀害，这哪里是峻法之下无人犯罪，严厉家庭没有强悍家奴呢？圣人知道这个道理，所以务求和谐而不求威严。因此高祖皇帝简化秦朝苛法，以此安慰对朝廷怨恨、憎恶的民众，培养民众的和睦之心，唯恐刑罚太重而恩德太薄。所以汉家恩德广施无穷无尽，德泽流于后世。商鞅、吴起认为秦国、楚国的法律太轻而增设法令，对上危害君主，对下殃及自身，这或许不是慈母不教育孩子的后果吧！”</p>',121)])])}const z=o(r,[["render",s]]);export{y as __pageData,z as default};
